UPDATE ui.dashboardquery SET
vcdashboardquery = 'SELECT X.* FROM   (VALUES (''Account'', ''Account''),(''VPA'', ''VPA''), (''Txn'', ''Txn'')) AS X ("label", "value") ;'::text WHERE
idashboardqueryid = 27 AND itenantid in (12,13);

UPDATE ui.dashboardquery SET
vcdashboardquery =  E'{
    "Txn":"SELECT X.* FROM   (VALUES (''Txn ID'', ''Txn ID''),(''RRN'', ''RRN'')) AS X (\\"label\\", \\"value\\")",
    "Other":"SELECT X.* FROM   (VALUES (''Payer'', ''Payer''),(''Payee'', ''Payee''), (''Both'', ''Both'')) AS X (\\"label\\", \\"value\\")"
}'::text,  bparametersrequired = true::boolean, vcfilterparametersjson = '{"Party": null}'::text WHERE
idashboardqueryid = 25 AND itenantid in (12,13);

