UPDATE ui.dashboardquery SET
vcdashboardquery = 'SELECT X.* FROM   (VALUES (''Account'', ''Account''),(''VPA'', ''VPA''), (''Txn'', ''Txn'')) AS X ("label", "value");'::text WHERE
idashboardqueryid = 27 AND itenantid in (19,9);

